def bubble(v):
    for i in range(len(v)):
        for j in range(len(v) - 1 - i):
            if v[j] > v[j + 1]: v[j], v[j + 1] = v[j + 1], v[j]
    return v

def selection(v):
    for i in range(len(v)):
        m = min(range(i, len(v)), key=v.__getitem__)
        v[i], v[m] = v[m], v[i]
    return v

def insertion(v):
    for i in range(1, len(v)):
        x, j = v[i], i - 1
        while j >= 0 and v[j] > x: v[j + 1] = v[j]; j -= 1
        v[j + 1] = x

def merge_sort(v):
    if len(v) <= 1: return v
    a, b = merge_sort(v[:len(v) // 2]), merge_sort(v[len(v) // 2:])
    return [(a if a and (not b or a[0] <= b[0]) else b).pop(0)
            for _ in range(len(a) + len(b))]

def gjej(v, x):
    for i, e in enumerate(v):
        if e == x: return i
    return -1

def maks_ne_3_dite(v):
    s = best = sum(v[:3])
    for i in range(3, len(v)):
        s += v[i] - v[i - 3]; best = max(best, s)
    return best

def kusuri(shuma, monedhat=(200, 100, 50, 20, 10, 5, 2, 1)):
    rez = []
    for m in monedhat:
        while shuma >= m: shuma -= m; rez.append(m)
    return rez

