def bfs(graf, fillimi):   # deque nga collections
    pare, radha = {fillimi}, deque([fillimi])
    while radha:
        for f in graf[radha.popleft()]:
            if f not in pare: pare.add(f); radha.append(f)

def dfs(graf, nyje, pare=None):
    pare = pare or set(); pare.add(nyje)
    for f in graf[nyje]:
        if f not in pare: dfs(graf, f, pare)
    return pare

