def te_thjeshtat(n):
    p = [True] * (n + 1); p[0] = p[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if p[i]: p[i * i::i] = [False] * len(p[i * i::i])
    return [i for i, x in enumerate(p) if x]

def faktoriali(n):
    return 1 if n <= 1 else n * faktoriali(n - 1)
print(faktoriali(5))   # 120

def fuqi(a, n, r=1):
    while n:
        if n & 1: r *= a
        a, n = a * a, n >> 1
    return r

